new file mode 100644
index 0000000..ddc9c70
--- /dev/null
+++ b/agent/src/club/streak.js
@@ -0,0 +1,28 @@
+export function streak(history, now = new Date()) {
+  const dayStart = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };
+  const mondayOf = (d) => { const x = dayStart(d); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; };
+  const today = dayStart(now);
+  const weeks = new Set();
+  for (const g of history || []) {
+    if (!g || typeof g.date !== "string") continue;
+    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(g.date);
+    if (!m) continue;
+    const gd = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
+    if (Number.isNaN(gd.getTime())) continue;
+    if (dayStart(gd).getTime() > today.getTime()) continue;
+    weeks.add(mondayOf(gd).getTime());
+  }
+  const thisMonday = mondayOf(now);
+  const thisWeek = thisMonday.getTime();
+  const prev = new Date(thisMonday);
+  prev.setDate(prev.getDate() - 7);
+  const lastWeek = prev.getTime();
+  let start = null;
+  if (weeks.has(thisWeek)) start = new Date(thisMonday);
+  else if (weeks.has(lastWeek)) start = prev;
+  else return 0;
+  let n = 0;
+  for (let w = start; weeks.has(w.getTime()); w.setDate(w.getDate() - 7)) n += 1;
+  return n;
+}
+export default streak;

